import { _decorator, Component, Node } from 'cc';
import { Entity } from './Engine/Entity';
import { Bus } from './Engine/Bus';
import { World } from './Engine/World';
import { ViewRegistry } from './Engine/ViewRegistry';
import { System } from './Engine/System';
import { TestView } from './TestView';

const { ccclass } = _decorator;

class TestEntity extends Entity {
    readonly kind = 'test';
    public vx = 100;
}

class MovementSystem implements System {
    onTick(world: World, dt: number): void {
        for (const e of world.query<TestEntity>('test')) {
            e.x += e.vx * dt;
            if (e.x > 300) {
                e.x = -300;  // 跑出右边就回左边
            }
        }
    }
}

@ccclass('TestRunner')
export class TestRunner extends Component {

    start() {
        const bus = new Bus();
        const views = new ViewRegistry(this.node);   // 所有 View 挂在 TestRunner 节点下

        // 注册工厂：kind = 'test' 的 Entity 用 TestView
        views.registerFactory('test', (e) => {
            const node = new Node(`view_${e.id}`);
            return node.addComponent(TestView);
        });

        const world = new World(bus, views);
        world.addSystem(new MovementSystem());

        // 创建 3 个 Entity
        for (let i = 0; i < 3; i++) {
            const e = new TestEntity();
            e.x = -300 + i * 100;
            e.y = i * 80 - 80;   // 错开 y 方便观察
            world.add(e);
        }

        world.start();

        // 每帧驱动
        this._world = world;
        this._views = views;
    }

    private _world: World = null!;
    private _views: ViewRegistry = null!;
    private _accumulator = 0;
    private readonly _fixedDt = 1 / 60;

    update(realDt: number) {
        this._accumulator += Math.min(realDt, 0.1);
        while (this._accumulator >= this._fixedDt) {
            this._world.tick(this._fixedDt);
            this._accumulator -= this._fixedDt;
        }
        this._views.syncAll(realDt);
    }
}